import json, os
S=os.getcwd(); css=open("base.css").read(); word=open("word.html").read()
W1=S+"/../w1"; W2=S+"/../w2"; W3=S+"/../w3"
BG="background:radial-gradient(120% 70% at 85% 0%,#163a2a 0%,#0b1626 55%,#07101c 100%)"
def page(w,h,body): return f"<!doctype html><html><head><meta charset=utf-8><style>{css}</style></head><body><div class='c' style='width:{w}px;height:{h}px'>{body}</div></body></html>"
def img(p,style=""): return f'<img src="file://{p}" style="{style}">'
WIN="display:block;width:100%;border-radius:22px;box-shadow:0 40px 80px -30px #000"
jobs=[]
def add(out,w,h,body,tr=False): jobs.append(dict(w=w,h=h,out=out,transparent=tr,html=page(w,h,body)))
SCREENS=[("phone","Your logbook, always up to date"),("import","Import your old logbook, even from photos"),("map","Your career on one map"),("ftl","Flight time limitations, worked out"),("signature","Sign your flights with your finger"),("licences","Licences and medical, never expired")]
def screen_inner(k,w):
    if k=="phone": return img(W1+"/ov/r23-phone.png",f"width:{int(w*1.0)}px;margin-top:-{int(w*0.36)}px;clip-path:inset({int(w*0.4)}px 0 {int(w*0.15)}px 0)")
    if k=="map": return img(W2+"/fm-dark-portrait.png",f"width:{int(w*0.8)}px;border-radius:24px")
    f={"import":W2+"/win-import.png","ftl":W2+"/win-ftl.png","signature":W3+"/win-signature-7.5.png","licences":W3+"/win-licences-7.5.png"}[k]
    return img(f,WIN)
# ---- launch video frames, vertical (1080x1920) and LinkedIn (1080x1350) ----
for (W,H,tag,capTop,boxTop) in [(1080,1920,"v",240,520),(1080,1350,"l",130,330)]:
    for k,cap in SCREENS:
        add(f"ov/launch-{tag}-{k}.png",W,H,f'<div style="position:absolute;inset:0;{BG}"></div><p style="position:absolute;left:80px;right:80px;top:{capTop}px;text-align:center;font:600 {72 if tag=="v" else 60}px/1.08 F">{cap}</p><div style="position:absolute;left:{70 if tag=="v" else 120}px;right:{70 if tag=="v" else 120}px;top:{boxTop}px;display:flex;justify-content:center">{screen_inner(k,940 if tag=="v" else 840)}</div>')
    add(f"ov/launch-{tag}-live.png",W,H,f'<p style="position:absolute;left:80px;right:80px;top:{int(H*0.17)}px;text-align:center;font:600 {120 if tag=="v" else 100}px/1 F;text-shadow:0 4px 30px #000a">Geardown<br>is live.</p>',True)
    add(f"ov/launch-{tag}-gear.png",W,H,f'<p style="position:absolute;left:80px;right:80px;top:{int(H*0.17)}px;text-align:center;font:600 {104 if tag=="v" else 92}px/1.05 F;text-shadow:0 4px 30px #000a">From gear up<br>to gear down.</p>',True)
    for var,l1,l2 in [("iphone","Now on iPhone and the web","30 days free · no card"),("web","Live on the web today","iPhone app coming soon")]:
        add(f"ov/launch-{tag}-end-{var}.png",W,H,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:0;right:0;top:{int(H*0.3)}px;display:flex;justify-content:center;transform:scale(1.5)">{word}</div><p style="position:absolute;left:60px;right:60px;top:{int(H*0.3)+170}px;text-align:center;font:600 62px/1.1 F;white-space:nowrap">{l1}</p><p class="mono green" style="position:absolute;left:0;right:0;top:{int(H*0.3)+330}px;text-align:center;font-size:54px;font-weight:700">{l2}</p><p class="mono" style="position:absolute;left:0;right:0;top:{int(H*0.3)+440}px;text-align:center;font-size:46px;color:#dbe4ee">geardown.app</p>' + ('' if var=="iphone" else f'<p style="position:absolute;left:0;right:0;top:{int(H*0.3)+530}px;text-align:center;font-size:34px;color:#93a6bc">Web version: 30 days free, no card</p>'))
# ---- story 14 Dec overlay ----
add("ov/s14.png",1080,1920,f'<div style="position:absolute;left:0;right:0;top:250px;display:flex;justify-content:center">{word}</div><p style="position:absolute;left:0;right:0;top:760px;text-align:center;font:600 150px/1 F;text-shadow:0 6px 40px #000a">Tomorrow.</p>',True)
# ---- stories 15 Dec ----
for var,l1 in [("iphone","Now on iPhone and the web"),("web","Live on the web today")]:
    add(f"out/ig-1512-story-1-live-{var}.png",1080,1920,f'{img(W1+"/dusk.png","position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:62% 50%")}<div style="position:absolute;inset:0;background:linear-gradient(180deg,#07101cee 0%,#07101c55 40%,#07101c77 62%,#07101cf2 100%)"></div><div style="position:absolute;left:0;right:0;top:250px;display:flex;justify-content:center">{word}</div><p style="position:absolute;left:0;right:0;top:400px;text-align:center;font:600 140px/1 F">It\'s live.</p><p style="position:absolute;left:80px;right:80px;top:580px;text-align:center;font:600 50px/1.2 M;color:#dbe4ee">{l1}</p><p class="mono green" style="position:absolute;left:0;right:0;bottom:360px;text-align:center;font-size:52px;font-weight:700">30 days free · no card</p><p style="position:absolute;left:0;right:0;bottom:280px;text-align:center;font-size:34px;color:#c9d4e2">Link below ↓</p>')
add("out/ig-1512-story-3-flightmap.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><p class="mono green" style="position:absolute;left:0;right:0;top:170px;text-align:center;font-size:72px;font-weight:700">#MyFlightmap</p><p style="position:absolute;left:80px;right:80px;top:280px;text-align:center;font:600 56px/1.15 F">Share yours, we\'ll repost our favourites</p><div style="position:absolute;left:150px;right:150px;top:480px">{img(W2+"/fm-dark-portrait.png","display:block;width:100%;border-radius:26px;box-shadow:0 40px 80px -30px #000")}</div><p style="position:absolute;left:0;right:0;bottom:110px;text-align:center;font-size:30px;color:#93a6bc">Example: demo pilot · Flightmap › Share</p>')
add("out/ig-1512-story-4-poll.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:0;right:0;top:250px;display:flex;justify-content:center">{word}</div><p style="position:absolute;left:80px;right:80px;top:420px;text-align:center;font:600 100px/1.05 F">What should we build next?</p><p style="position:absolute;left:0;right:0;bottom:300px;text-align:center;font-size:34px;color:#93a6bc">Every answer is read.</p>')
# ---- LI 16 Dec PDF 8 pages ----
jobsill='<div style="border:2px solid #ffffff22;border-radius:22px;padding:26px">'+"".join(f'<div style="padding:16px 0;{"border-top:1px solid #ffffff14" if i else ""}"><div style="display:flex;justify-content:space-between;font-size:30px"><b>{a}</b><b style="color:{c}">{p}%</b></div><p style="font-size:24px;color:#93a6bc;margin-top:4px">{b}</p><div style="height:10px;border-radius:5px;background:#ffffff14;margin-top:12px"><div style="height:100%;width:{p}%;border-radius:5px;background:{c}"></div></div></div>' for i,(a,b,p,c) in enumerate([("Business jet operator","Captain · Citation Latitude",100,"#4ade80"),("Charter airline","First Officer · A320",86,"#38bdf8"),("Regional airline","First Officer · ATR 72",71,"#38bdf8")]))+'<p style="font-size:22px;color:#93a6bc;margin-top:12px">Illustration · sorted by your hours, type and licences</p></div>'
expo='<div style="display:flex;gap:16px;flex-wrap:wrap">'+"".join(f'<span style="border:2px solid {c};border-radius:999px;padding:14px 28px;font:700 34px J">{x}</span>' for x,c in [("EASA","#4ade80"),("FAA","#4ade80"),("CASA","#4ade80"),("PDF","#ffffff40"),("CSV","#ffffff40"),("Excel","#ffffff40")])+'</div>'
pages=[("Import","Your old logbook, even from photos",img(W2+"/win-import.png",WIN)),
 ("Logbook","Right, column by column",img(S+"/win-logbook.png",WIN)),
 ("Flightmap","Your career on one map",img(W2+"/fm-dark-square.png","display:block;width:80%;margin:0 auto;border-radius:24px")),
 ("FTL","Limits worked out from your logbook and roster",img(W2+"/win-ftl.png",WIN)),
 ("Licences","Every expiry tracked, recency checked",img(W3+"/win-licences-7.5.png",WIN)),
 ("Signatures","Sign with your finger, or ask a captain",img(W3+"/win-signature-7.5.png",WIN)),
 ("Career","Your CV and the jobs that fit you",jobsill),
 ("Exports","Your logbook stays yours",expo)]
for i,(lab,title,vis) in enumerate(pages):
    add(f"out/li-1612-doc-{i+1}.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px;transform:scale(.8);transform-origin:left top">{word}</div><p class="mono" style="position:absolute;right:84px;top:92px;font-size:22px;color:#93a6bc">{i+1} / 8</p><div style="position:absolute;left:84px;right:84px;top:220px"><p class="mono green" style="font-size:26px;letter-spacing:.16em;font-weight:700">{lab.upper()}</p><h2 style="font:600 72px/1.06 F;margin-top:16px">{title}</h2><div style="margin-top:60px">{vis}</div></div>'+('<p style="position:absolute;left:84px;right:84px;bottom:70px;font-size:32px;color:#c9d4e2">30 days free, no card · <span class="mono green">geardown.app</span></p>' if i==7 else ''))
# ---- IG carousel 17 Dec: first 10 minutes ----
steps=[("Create your account","30 days free, no card.",img(S+"/signup.png","display:block;width:62%;margin:0 auto;border-radius:24px;box-shadow:0 40px 80px -30px #000")),
 ("Import your old logbook","Excel, CSV, LogTen, Safelog, CrewLounge or photos.",img(W2+"/win-import.png",WIN)),
 ("Check your totals","Compare them with your last page before saving.",img(W2+"/win-import.png",WIN+";clip-path:inset(72% 0 0 0);margin-top:-300px")),
 ("Add licences and medical","Reminders before anything expires.",img(W3+"/win-licences-7.5.png",WIN)),
 ("Log your next flight","Type the registration, the rest fills in.",img(S+"/form-final.png","display:block;width:62%;margin:0 auto;border-radius:24px;box-shadow:0 40px 80px -30px #000;clip-path:inset(0 0 40% 0)")),
 ("Share your Flightmap","One tap, dark or light.",img(W2+"/fm-dark-square.png","display:block;width:70%;margin:0 auto;border-radius:24px"))]
add("out/ig-1712-first-10-min-1.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px">{word}</div><div style="position:absolute;left:84px;right:84px;top:300px"><p class="mono green" style="font-size:26px;letter-spacing:.16em;font-weight:700">GETTING STARTED</p><h1 style="font:600 116px/1.0 F;letter-spacing:-.02em;margin-top:20px">Your first 10 minutes on Geardown</h1></div><p style="position:absolute;right:84px;bottom:84px;font:700 30px M;color:#4ade80">Swipe →</p><p style="position:absolute;left:84px;bottom:90px;font-size:28px;color:#93a6bc">Save this 📌</p>')
for i,(t,sub,vis) in enumerate(steps):
    add(f"out/ig-1712-first-10-min-{i+2}.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px;transform:scale(.8);transform-origin:left top">{word}</div><p class="mono" style="position:absolute;right:84px;top:92px;font-size:22px;color:#93a6bc">{i+2} / 7</p><div style="position:absolute;left:84px;right:84px;top:210px"><p class="mono green" style="font-size:30px;font-weight:700">STEP {i+1}</p><h2 style="font:600 76px/1.05 F;margin-top:12px">{t}</h2><p style="font-size:36px;color:#c9d4e2;margin-top:16px">{sub}</p></div><div style="position:absolute;left:84px;right:84px;top:{560 if i not in (0,4) else 520}px;max-height:780px;overflow:hidden">{vis}</div>')
# ---- reel 18 Dec overlays ----
add("ov/r18-a.png",1080,1920,'<p style="position:absolute;left:80px;right:80px;top:120px;text-align:center;font:600 84px/1.08 F;text-shadow:0 4px 30px #000a">Your routes, your map.</p>',True)
add("ov/r18-end.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><p class="mono green" style="position:absolute;left:0;right:0;top:700px;text-align:center;font-size:110px;font-weight:700">#MyFlightmap</p><p style="position:absolute;left:80px;right:80px;top:880px;text-align:center;font:600 60px/1.15 F">Share yours: we\'ll feature some next week.</p><div style="position:absolute;left:0;right:0;top:1200px;display:flex;justify-content:center">{word}</div>')
for th in ["dark","light"]:
    add(f"ov/r18-{th}.png",1080,1920,f'<div style="position:absolute;inset:0;background:#07101c"></div><div style="position:absolute;left:90px;right:90px;top:420px">{img(W2+f"/fm-{th}-portrait.png","display:block;width:100%;border-radius:26px")}</div>')
# ---- LI 19 Dec thank you ----
add("out/li-1912-thank-you.png",1080,1350,f'{img(W1+"/day.png","position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:40% 50%")}<div style="position:absolute;inset:0;background:linear-gradient(180deg,#07101cdd 0%,#07101c40 35%,#07101c40 55%,#07101cf2 80%)"></div><div style="position:absolute;left:84px;top:84px">{word}</div><div style="position:absolute;left:84px;right:84px;bottom:110px"><h1 style="font:600 96px/1.02 F">Thank you.</h1><p style="font-size:36px;line-height:1.4;color:#dbe4ee;margin-top:20px">To every pilot who tried Geardown this week. What should we build next?</p><p class="mono green" style="font-size:28px;margin-top:26px">Happy holidays · safe flights</p></div>')
json.dump(jobs,open("jobs4.json","w")); print(len(jobs))
